from __future__ import annotations
import cmath
import math

def cycle_comparison(n: int) -> None:
    if n < 3:
        raise ValueError("n must be at least 3")
    for k in range(n):
        zeta = cmath.exp(2j * math.pi * k / n)
        character_sum = zeta + 1 / zeta
        cosine_value = 2 * math.cos(2 * math.pi * k / n)
        print(k, character_sum, cosine_value, abs(character_sum - cosine_value))

if __name__ == "__main__":
    cycle_comparison(12)

from __future__ import annotations
import cmath
import math
from collections.abc import Sequence

def adjacency(n: int, steps: Sequence[int], f: Sequence[complex]) -> list[complex]:
    return [sum(f[(x + s) % n] for s in steps) for x in range(n)]

def check_mode(n: int, steps: Sequence[int], k: int) -> float:
    chi = [cmath.exp(2j * math.pi * k * x / n) for x in range(n)]
    lam = sum(cmath.exp(2j * math.pi * k * s / n) for s in steps)
    return max(abs(a - lam * b) for a, b in zip(adjacency(n, steps, chi), chi))

if __name__ == "__main__":
    for k in range(9):
        print(k, check_mode(9, (1, 2, 8), k))

