from __future__ import annotations
import cmath
import math
from collections.abc import Iterable

def direct_character_spectrum(n: int, steps: Iterable[int]) -> list[complex]:
    if n < 1:
        raise ValueError("n must be positive")
    residues = sorted({s % n for s in steps})
    return [sum(cmath.exp(2j * math.pi * k * s / n) for s in residues)
            for k in range(n)]

from __future__ import annotations
import cmath
import math
from collections.abc import Sequence

def fft(values: Sequence[complex]) -> list[complex]:
    n = len(values)
    if n == 1:
        return [values[0]]
    if n == 0 or n & (n - 1):
        raise ValueError("length must be a positive power of two")
    even = fft(values[0::2])
    odd = fft(values[1::2])
    out = [0j] * n
    for k in range(n // 2):
        twiddle = cmath.exp(2j * math.pi * k / n) * odd[k]
        out[k] = even[k] + twiddle
        out[k + n // 2] = even[k] - twiddle
    return out

def cayley_spectrum_fft(n: int, steps: Sequence[int]) -> list[complex]:
    indicator = [0j] * n
    for s in set(step % n for step in steps):
        indicator[s] = 1 + 0j
    return fft(indicator)

